import { TiltedCard, TiltedCardLayer } from "solen-design/react";

<TiltedCard
  imageSrc="/cover.jpg"
  altText="封面"
  captionText="点一下翻面"
  containerWidth={300}
  containerHeight={236}
  imageWidth={300}
  imageHeight={236}
  radius={16}
  rotateAmplitude={12}
  scaleOnHover={1.05}
  smoothness={0.6}
  glare={0.5}
  glareColor="#ffffff"
  shadow={0.5}
  parallax={1}
  axis="both"
  showTooltip={true}
  floating={false}
  trackWindow={false}
  backContent={<div>背面</div>}
  onClick={() => console.log("clicked")}
>
  <TiltedCardLayer depth={40}>
    <span>浮层文字</span>
  </TiltedCardLayer>
</TiltedCard>
